// Generated by `npm run import:cwt` from cwtools-stellaris-config, then maintained by hand.
// Re-running the importer proposes a diff; it never overwrites hand edits automatically.

import { DefinitionTypeId, ScopeId } from "../catalog.js";

import {
  always,
  between,
  block,
  defineType,
  definitionLocalisation,
  effectEntries,
  field,
  item,
  keyedBlocks,
  modifierEntries,
  modifierRuleEntries,
  namingStrings,
  occurs,
  replaceScope,
  triggerEntries,
  typeRef,
} from "../ir.js";

import type { DefinitionType } from "../ir.js";

export const policy: DefinitionType = defineType({
  id: DefinitionTypeId.Policy,
  source: keyedBlocks("common/policies"),
  variants: [{ id: "policy_option", when: always() }],
  localisation: [
    definitionLocalisation("Name", "policy_$", true),
    definitionLocalisation("Description", "policy_$_desc", true),
  ],
  modifiers: [],
  entries: [
    field("potential", block([triggerEntries()]), occurs.optional),
    field("allow", block([triggerEntries()]), occurs.optional),
    field("on_activate", block([effectEntries()]), occurs.optional, {
      documentation: "Fires when the policy group first becomes available",
    }),
    field(
      "option",
      block([
        // The option's own string and its description: the policy's check
        // (`0x502b10`) asks each option for both (`0x4ffdf0`), and logs
        // "Missing Policy Localization Key" for either one it cannot find.
        field("name", namingStrings("localisation", "$", "$_desc"), occurs.one),
        field("icon", typeRef("sprite"), occurs.optional),
        field("pre_sapient_purge", typeRef("purge_type"), occurs.optional),
        field(
          "in_breach_of",
          block([
            item(
              block([
                field("trigger", block([triggerEntries()]), occurs.optional, {
                  scope: replaceScope({ root: ScopeId.Country }),
                }),
                field("key", typeRef("resolution"), occurs.one),
              ]),
              occurs.any,
            ),
          ]),
          occurs.any,
        ),
        // Each flag is registered as it is read, and its `<flag>_name` looked up
        // there and then (`0x4fee10`): vanilla gives every one of its 148 a
        // string, most of them `$<option>$`.
        field("policy_flags", block([item(namingStrings("scalar", "$_name"), between(0, 10))]), occurs.optional),
        field("on_enabled", block([effectEntries()]), occurs.optional),
        field("on_disabled", block([effectEntries()]), occurs.optional),
        field("potential", block([triggerEntries()]), occurs.optional),
        field("valid", block([triggerEntries()]), occurs.optional),
        field("modifier", block([modifierEntries()]), occurs.optional, {
          scope: replaceScope({ root: ScopeId.Country }),
        }),
        field("prerequisites", block([item(typeRef("technology"), occurs.one)]), occurs.optional),
        field("AI_weight", block([modifierRuleEntries()]), occurs.optional),
      ]),
      between(1, 20),
    ),
  ],
});
